+      const double w = Tr.Weight() * ip.weight;
+      vqfc.Eval(temp, Tr, ip);
+      fe.CalcShape(ip, shape);
+      for (int ind = 0; ind < vdim; ind++) {
+         for(int nd = 0; nd < ndofs; nd++){
+            elvect(nd + ind * ndofs) += w * shape(nd) * temp(ind); 
