+/// Templated version of CalcBinomTerms
+template<typename float_type>
+void CalcBinomTerms(const int p, const float_type x, const float_type y, float_type* u, float_type* d)
+{
+    if (p == 0)
+    {
+       u[0] = float_type(1.);
+       d[0] = float_type(0.);
+    }
+    else
+    {
+       int i;
+       const int *b = Poly_1D::Binom(p);
+       const float_type xpy = x + y, ptx = p*x;
+       float_type z = float_type(1.);
+
+       for (i = 1; i < p; i++)
+       {
+          d[i] = b[i]*z*(i*xpy - ptx);
+          z *= x;
+          u[i] = b[i]*z;
+       }
+       d[p] = p*z;
+       u[p] = z*x;
+       z = float_type(1.);
+       for (i--; i > 0; i--)
+       {
+          d[i] *= z;
+          z *= y;
+          u[i] *= z;
+       }
+       d[0] = -p*z;
+       u[0] = z*y;
+    }
+
+}
