void CalcBinomTerms(const int p, const float_type x, const float_type y, float_type* u)
{
    if (p == 0)
    {
        u[0] = float_type(1.);
    }
    else
    {
        int i;
        const int *b = Poly_1D::Binom(p);
        float_type z = x;
        for (i = 1; i < p; i++)
        {
            u[i] = b[i]*z;
            z *= x;
        }
        u[p] = z;
        z = y;
        for (i--; i > 0; i--)
        {
            u[i] *= z;
            z *= y;
        }
        u[0] = z;
    }
}

void CalcBinomTerms(const int p, const float_type x, const float_type y, float_type* u, float_type* d)
{
    if (p == 0)
    {
       u[0] = float_type(1.);
       d[0] = float_type(0.);
    }
    else
    {
       int i;
       const int *b = Poly_1D::Binom(p);
       const float_type xpy = x + y, ptx = p*x;
       float_type z = float_type(1.);

       for (i = 1; i < p; i++)
       {
          d[i] = b[i]*z*(i*xpy - ptx);
          z *= x;
          u[i] = b[i]*z;
       }
       d[p] = p*z;
       u[p] = z*x;
       z = float_type(1.);
       for (i--; i > 0; i--)
       {
          d[i] *= z;
          z *= y;
          u[i] *= z;
       }
       d[0] = -p*z;
       u[0] = z*y;
    }

}

void CalcDBinomTerms(const int p, const float_type x,
                     const float_type y, float_type* d)
{
    if (p == 0)
    {
       d[0] = 0.;
    }
    else
    {
       int i;
       const int *b = Poly_1D::Binom(p);
       const float_type xpy = x + y, ptx = p*x;
       float_type z = float_type(1.);

       for (i = 1; i < p; i++)
       {
          d[i] = b[i]*z*(i*xpy - ptx);
          z *= x;
       }
       d[p] = p*z;
       z = float_type(1.);
       for (i--; i > 0; i--)
       {
          d[i] *= z;
          z *= y;
       }
       d[0] = -p*z;
    }
}

void CalcBernstein(const int p, const float_type x, float_type *u)
{
    CalcBinomTerms(p, x, 1. - x, u);
}

void CalcBernstein(const int p, const float_type x,
                   float_type *u, float_type *d)
{
    CalcBinomTerms(p, x, 1. - x, u, d);
}

