    : M(-1), N(-1), depth(-1), pgm8(NULL), pgm16(NULL)
 {
    ifstream in(filename);
    if (!in)
    {
       // Abort with an error message
       MFEM_ABORT("Image file not found: " << filename << '\n');
    }

    ReadMagicNumber(in);
