 void KnotVector::Flip()
 {
    double apb = knot(0) + knot(knot.Size()-1);

    int ns = (NumOfControlPoints - Order)/2;
    for (int i = 1; i <= ns; i++)
    {
       double tmp = apb - knot(Order + i);
       knot(Order + i) = apb - knot(NumOfControlPoints - i);
       knot(NumOfControlPoints - i) = tmp;
    }
 }

