void ParGridFunction::CountElementsPerVDof(Array<int> &elem_per_vdof) const
{
   GridFunction::CountElementsPerVDof(elem_per_vdof);
   // Count the zones globally.
   GroupCommunicator &gcomm = this->ParFESpace()->GroupComm();
