# Full function context (WaRF function-aware diff)

void solveLU(int nCon, real_t* AA1, real_t* bb1)
{
   // Solve linear system with LU decomposition ifndef LAPACK
   int nLAP = nCon + 1;
   int* ipiv = new int[nLAP];

   // Convert AA1 to matrix A and bb1 to vector B
   real_t** A = new real_t*[nLAP];
   for (int i = 0; i < nLAP; ++i)
   {
      A[i] = new real_t[nLAP];
   }
   real_t* B = new real_t[nLAP];
   for (int i = 0; i < nLAP; ++i)
   {
      for (int j = 0; j < nLAP; ++j)
      {
         A[i][j] = AA1[j * nLAP + i];
      }
      B[i] = bb1[i];
   }

   // Perform LU decomposition
   real_t** L = new real_t*[nLAP];
   real_t** U = new real_t*[nLAP];
   for (int i = 0; i < nLAP; ++i)
   {
      L[i] = new real_t[nLAP];
      U[i] = new real_t[nLAP];
      for (int j = 0; j < nLAP; ++j)
      {
         L[i][j] = 0.0;
         U[i][j] = 0.0;
      }
   }

   for (int i = 0; i < nLAP; ++i)
   {
      for (int k = i; k < nLAP; ++k)
      {
         real_t sum = 0.0;
         for (int j = 0; j < i; ++j)
         {
            sum += (L[i][j] * U[j][k]);
         }
         U[i][k] = A[i][k] - sum;
      }
      for (int k = i; k < nLAP; ++k)
      {
         if (i == k)
         {
            L[i][i] = 1.0;
         }
         else
         {
            real_t sum = 0.0;
            for (int j = 0; j < i; ++j)
            {
               sum += (L[k][j] * U[j][i]);
            }
            L[k][i] = (A[k][i] - sum) / U[i][i];
         }
      }
   }

   // Check for singular matrix
   for (int i = 0; i < nLAP; ++i)
   {
      if (U[i][i] == 0.0)
      {
         delete[] ipiv;
         for (int j = 0; j < nLAP; ++j)
         {
            delete[] A[j];
            delete[] L[j];
            delete[] U[j];
         }
         delete[] A;
         delete[] L;
         delete[] U;
         delete[] B;
         MFEM_ABORT("Error: matrix in MMA LU Solve is singular.");
      }
   }

   // Forward substitution to solve L * Y = B
   real_t* Y = new real_t[nLAP];
   for (int i = 0; i < nLAP; ++i)
   {
      real_t sum = 0.0;
      for (int j = 0; j < i; ++j)
      {
         sum += L[i][j] * Y[j];
      }
      Y[i] = (B[i] - sum) / L[i][i];
   }

   // Backward substitution to solve U * X = Y
   real_t* X = new real_t[nLAP];
   for (int i = nLAP - 1; i >= 0; --i)
   {
      real_t sum = 0.0;
      for (int j = i + 1; j < nLAP; ++j)
      {
         sum += U[i][j] * X[j];
      }
      X[i] = (Y[i] - sum) / U[i][i];
   }

   delete[] ipiv;

   // Copy results back to bb1
   for (int i = 0; i < (nCon + 1); i++)
   {
      bb1[i] = X[i];
   }

   // Clean up dynamically allocated memory
   for (int i = 0; i < nLAP; ++i)
   {
      delete[] A[i];
      delete[] L[i];
      delete[] U[i];
   }
   delete[] A;
   delete[] L;
   delete[] U;
   delete[] B;
   delete[] Y;
   delete[] X;
}

               else if (info > 0)
