      blf.AddDomainIntegrator(new MassIntegrator(one, ir));
      blf.SetAssemblyLevel(AssemblyLevel::PARTIAL);
      blf.Assemble();
      blf.Mult(x, y);
      fes.GetProlongationMatrix()->MultTranspose(y, Y);

      static constexpr int U = 0, Coords = 1;
